@Entity @Table(name="document_check_decision",uniqueConstraints=@UniqueConstraint(columnNames={"lc_id","finding_code","document_name","finding_fingerprint"})) public class DocumentCheckDecision extends de.ostms.lc.tenant.domain.TenantOwnedEntity {@Id private UUID id=UUID.randomUUID();@Column(name="lc_id",nullable=false)private UUID lcId;@Column(name="finding_code",nullable=false,length=100)private String findingCode;@Column(name="document_name",nullable=false)private String documentName="";@Column(nullable=false,length=30)private String decision;@Column(length=1000)private String comment;@Column(nullable=false,length=100)private String reviewedBy;@Column(nullable=false)private LocalDateTime reviewedAt=LocalDateTime.now();@Column(name="finding_fingerprint",length=64) private String findingFingerprint;@Column(name="rule_catalog_version",length=40) private String ruleCatalogVersion;@Column(name="rule_id",length=100) private String ruleId;@Column(name="rule_version",length=40) private String ruleVersion;@Column(name="finding_snapshot",columnDefinition="text") private String findingSnapshot;public String getFindingFingerprint(){return findingFingerprint;}public void setFindingFingerprint(String v){findingFingerprint=v;}public String getRuleCatalogVersion(){return ruleCatalogVersion;}public void setRuleCatalogVersion(String v){ruleCatalogVersion=v;}public String getRuleId(){return ruleId;}public void setRuleId(String v){ruleId=v;}public String getRuleVersion(){return ruleVersion;}public void setRuleVersion(String v){ruleVersion=v;}public String getFindingSnapshot(){return findingSnapshot;}public void setFindingSnapshot(String v){findingSnapshot=v;}@Column(name="invalidated_at") private LocalDateTime invalidatedAt;public LocalDateTime getInvalidatedAt(){return invalidatedAt;}public void setInvalidatedAt(LocalDateTime v){invalidatedAt=v;}public UUID getId(){return id;}public UUID getLcId(){return lcId;}public void setLcId(UUID v){lcId=v;}public String getFindingCode(){return findingCode;}public void setFindingCode(String v){findingCode=v;}public String getDocumentName(){return documentName;}public void setDocumentName(String v){documentName=v==null?"":v;}public String getDecision(){return decision;}public void setDecision(String v){decision=v;}public String getComment(){return comment;}public void setComment(String v){comment=v;}public String getReviewedBy(){return reviewedBy;}public void setReviewedBy(String v){reviewedBy=v;}public LocalDateTime getReviewedAt(){return reviewedAt;}public void setReviewedAt(LocalDateTime v){reviewedAt=v;}}
